        p=self._particles[particle_id]
        if p.status=='pruned': raise InvalidActionError('pruned')
        if self._nfe+1>self.budget: raise BudgetExceededError()
        self._nfe+=1
        aid=self._next_aid; self._next_aid+=1
        score=0.6 + 0.24*p.time + 0.01*(particle_id % 5) - 0.005*(particle_id // 5)
        unc=max(0.0,1.0-p.time)
        preview=PreviewRecord(id=aid,particle_id=particle_id,time=p.time,score=score,uncertainty=unc,score_dict={})
        self._previews[aid]=preview
        p.last_preview_id=aid
        return preview
    def backward(self,anchor_id,target_time,noise_policy='fresh_noise',num_children=1,mask=None,strength=1.0):
        if anchor_id not in self._previews: raise InvalidActionError('anchor')
        ids=[]
        time=max(t for t in self.time_grid if t<=target_time+1e-9)
        for _ in range(num_children):
            pid=self._next_pid; self._next_pid+=1
            self._particles[pid]=P(pid,time=time)
            ids.append(pid)
        return ids
    def prune(self,particle_ids):
        for pid in particle_ids:
            p=self._particles[pid]
            if p.status=='completed': raise InvalidActionError('completed')
            p.status='pruned'
    def answer(self,rule='best_preview_score'):
        if rule=='best_preview_score' and self._previews:
            best=max(self._previews.values(), key=lambda x:x.score)
            return AnswerRecord(best.particle_id,best.id,(),best.score,self._nfe,rule,[],{})
        live=[p for p in self._particles.values() if p.status in ('active','completed')]
        pid=max(live,key=lambda p:(p.time,p.id)).id if live else None
        return AnswerRecord(pid,None,(),None,self._nfe,rule,[],{})
    def get_state(self):
        return ControllerState(
            prompt='x', budget_left=self.budget_left,
            active_particle_ids=[p.id for p in self._particles.values() if p.status=='active'],
            completed_particle_ids=[p.id for p in self._particles.values() if p.status=='completed'],
            pruned_particle_ids=[p.id for p in self._particles.values() if p.status=='pruned'],
            particles={pid: ParticleSummary(id=pid,time=p.time,parent_id=None,source_anchor_id=None,nfe_used=0,status=p.status,last_preview_id=p.last_preview_id,num_children=0) for pid,p in self._particles.items()},
            previews=dict(self._previews), event_log=[])

controller=OptimalController()
